MATCH (o:OpenItem)
WHERE o.raised <= $d
AND NOT EXISTS {
  MATCH (p:Person)-[own:OWNS]->(o)
  WHERE own.from <= $d AND (own.to IS NULL OR own.to > $d)
}
AND NOT EXISTS {
  MATCH (dec:Decision)-[:CLOSES]->(o)
  WHERE dec.date <= $d
}
OPTIONAL MATCH (m:Meeting)<-[:RAISED_IN]-(o)
RETURN o.key AS key, o.text AS text, o.raised AS raised, o.status AS status, m.file AS file, m.date AS meeting_date
ORDER BY o.raised, o.key

