args.query:
MATCH (o:OpenItem)
WHERE o.raised <= $d
  AND NOT EXISTS {
    MATCH (p:Person)-[own:OWNS]->(o)
    WHERE own.from <= $d AND (own.to IS NULL OR own.to > $d)
  }
  AND NOT EXISTS {
    MATCH (dec:Decision)-[:CLOSES]->(o)
    WHERE dec.date <= $d
  }
RETURN o.text AS text, o.raised AS raised, o.status AS status, o.key AS key, o.id AS id, o.raised_again AS raised_again
ORDER BY o.raised, o.key

