args.query:
MATCH (o:OpenItem)
WHERE o.raised <= $d
AND NOT EXISTS {
  MATCH (:Person)-[ow:OWNS]->(o)
  WHERE ow.from <= $d AND (ow.to IS NULL OR ow.to > $d)
}
AND NOT EXISTS {
  MATCH (dec:Decision)-[:CLOSES]->(o)
  WHERE dec.date <= $d
}
OPTIONAL MATCH (o)<-[:CLOSES]-(dec:Decision)
RETURN o.key AS key, o.text AS text, o.raised AS raised, coalesce(size(o.raised_again), 0) + 1 AS raised_times
ORDER BY raised, key

